    expect(() => {
      assignError(undefined, {}, plugins);
    }).toThrow(TypeError);

    expect(() => {
      assignError('string', {}, plugins);
    }).toThrow(TypeError);
  });

  test.skip('should throw TypeError when newProps is not an object', () => {
    const error = {};
    const plugins = [];

    expect(() => {
      assignError(error, null, plugins);
    }).toThrow(TypeError);

    expect(() => {
      assignError(error, 'string', plugins);
    }).toThrow(TypeError);
  });

  test.skip('should throw TypeError when plugins is not an array', () => {
    const error = {};
