      assignError(error, newProps, 'string');
    }).toThrow(TypeError);
  });

  test.skip('should handle plugins without instanceMethods property', () => {
    const error = {};
    const plugins = [
      {}, // Plugin without instanceMethods
      { instanceMethods: { excludedMethod: () => {} } }
    ];

    assignError(error, {
      code: 'ERROR_CODE',
      someProp: 'value',
