const { callInstanceMethod } = require('../../../../src/plugins/instance/call');

class CustomError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CustomError';
  }

  customMethod(plugin, plugins, ...args) {
    return {
      message: this.message,
      plugin: plugin?.name,
      plugins: plugins?.length,
      args
    };
  }

  voidMethod() {
    // Method that returns undefined
  }
}

class AnotherError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AnotherError';
  }
}

describe('callInstanceMethod', () => {
  let errorInstance;
  let methodFunc;
  let methodName;
  let plugin;
   let plugins;
  let args;

  beforeEach(() => {
    errorInstance = new CustomError('Test error');
    methodFunc = errorInstance.customMethod.bind(errorInstance);
    methodName = 'customMethod';
    plugin = { name: 'testPlugin' };
    plugins = [{ name: 'plugin1' }, { name: 'plugin2' }];
    args = ['arg1', 'arg2'];
  });

  test.skip('should successfully call method when all parameters are valid', () => {
