      args
    );

    expect(result).toEqual({
      message: 'Test error',
      plugin: 'testPlugin',
      plugins: 2,
      args: ['arg1', 'arg2']
    });
  });

  test('should throw TypeError when error is not instance of ErrorClass', () => {
    const wrongError = new AnotherError('Wrong error type');

    expect(() => {
      callInstanceMethod(
        wrongError,
        methodFunc,
        methodName,
        plugin,
        plugins,
        CustomError,
        args
      );
    }).toThrow(TypeError);
  });

  test.skip('should work with null plugin', () => {
    const result = callInstanceMethod(
      errorInstance,
      methodFunc,
      methodName,
      null,
      plugins,
      CustomError,
      args
    );

    expect(result).toEqual({
      message: 'Test error',
      plugin: null,
      plugins: 2,
      args: ['arg1', 'arg2']
    });
  });

  test.skip('should work with empty plugins array', () => {
    const result = callInstanceMethod(
      errorInstance,
      methodFunc,
      methodName,
      plugin,
      [],
      CustomError,
      args
    );

    expect(result).toEqual({
      message: 'Test error',
      plugin: 'testPlugin',
      plugins: 0,
      args: ['arg1', 'arg2']
    });
  });

  test.skip('should work with empty args array', () => {
    const result = callInstanceMethod(
      errorInstance,
      methodFunc,
      methodName,
      plugin,
      plugins,
      CustomError,
      []
    );

    expect(result).toEqual({
      message: 'Test error',
      plugin: 'testPlugin',
      plugins: 2,
      args: []
    });
  });

  test.skip('should handle method that returns undefined', () => {
    const result = callInstanceMethod(
      errorInstance,
      errorInstance.voidMethod.bind(errorInstance),
      'voidMethod',
      plugin,
      plugins,
      CustomError,
      args
    );

    expect(result).toBeUndefined();
  });

  test.skip('should handle method with no additional parameters', () => {
    const simpleMethod = function() { return this.message; };
    const result = callInstanceMethod(
      errorInstance,
      simpleMethod.bind(errorInstance),
      'simpleMethod',
      undefined,
      undefined,
      CustomError,
      []
    );

    expect(result).toBe('Test error');
  });

  test.skip('should preserve error object integrity', () => {
