  test('should throw TypeError for null error', () => {
    expect(() => {
      callInstanceMethod(
        null,
        methodFunc,
        methodName,
        plugin,
        plugins,
        CustomError,
        args
      );
    }).toThrow(TypeError);
  });

  test('should throw TypeError for undefined error', () => {
    expect(() => {
      callInstanceMethod(
        undefined,
        methodFunc,
        methodName,
        plugin,
        plugins,
        CustomError,
        args
      );
    }).toThrow(TypeError);
  });
});

