import { deepClone } from '../../../src/options/clone';

describe('deepClone', () => {
  test('should return primitive values directly', () => {
    expect(deepClone(42)).toBe(42);
    expect(deepClone('hello')).toBe('hello');
    expect(deepClone(true)).toBe(true);
    expect(deepClone(null)).toBe(null);
    expect(deepClone(undefined)).toBe(undefined);
  });

  test('should clone arrays with primitive values', () => {
    const original = [1, 2, 3, 'test', true];
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original); // Should be different references
  });

  test('should clone nested arrays', () => {
    const original = [1, [2, 3], [4, [5, 6]]];
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned[1]).not.toBe(original[1]); // Nested array should be different reference
    expect(cloned[2]).not.toBe(original[2]);
    expect(cloned[2][1]).not.toBe(original[2][1]); // Deeply nested array should be different reference
  });

  test('should clone plain objects with primitive values', () => {
    const original = { a: 1, b: 'test', c: true, d: null };
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original); // Should be different references
  });

  test('should clone nested objects', () => {
    const original = {
      a: 1,
      b: {
        c: 2,
        d: {
          e: 3,
          f: 'test'
        }
      }
    };
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.b).not.toBe(original.b); // Nested object should be different reference
    expect(cloned.b.d).not.toBe(original.b.d); // Deeply nested object should be different reference
  });

  test('should clone mixed arrays and objects', () => {
    const original = {
      arr: [1, { nested: 'value' }, 3],
      obj: {
        innerArr: ['a', 'b'],
        prop: 42
      }
    };
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.arr).not.toBe(original.arr);
    expect(cloned.obj).not.toBe(original.obj);
    expect(cloned.arr[1]).not.toBe(original.arr[1]);
    expect(cloned.obj.innerArr).not.toBe(original.obj.innerArr);
  });

  test('should handle empty arrays and objects', () => {
    const emptyArray = [];
    const emptyObject = {};

    const clonedArray = deepClone(emptyArray);
    const clonedObject = deepClone(emptyObject);

    expect(clonedArray).toEqual(emptyArray);
    expect(clonedArray).not.toBe(emptyArray);
    expect(clonedObject).toEqual(emptyObject);
    expect(clonedObject).not.toBe(emptyObject);
  });

  test('should preserve original object immutability', () => {
    const original = { a: 1, b: { c: 2 } };
    const cloned = deepClone(original);

    // Modify cloned object
    cloned.a = 999;
    cloned.b.c = 888;

    // Original should remain unchanged
    expect(original.a).toBe(1);
    expect(original.b.c).toBe(2);
  });

  test('should handle complex nested structures', () => {
    const original = {
      level1: {
        level2: {
          level3: {
            array: [1, 2, { deep: 'value' }],
            primitive: 'test'
          }
        },
        array: [
          { nested: { deeper: 'value' } },
          [1, 2, [3, 4]]
        ]
      }
    };

    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.level1).not.toBe(original.level1);
    expect(cloned.level1.level2).not.toBe(original.level1.level2);
    expect(cloned.level1.level2.level3).not.toBe(original.level1.level2.level3);
    expect(cloned.level1.level2.level3.array).not.toBe(original.level1.level2.level3.array);
    expect(cloned.level1.level2.level3.array[2]).not.toBe(original.level1.level2.level3.array[2]);
    expect(cloned.level1.array).not.toBe(original.level1.array);
    expect(cloned.level1.array[0]).not.toBe(original.level1.array[0]);
    expect(cloned.level1.array[0].nested).not.toBe(original.level1.array[0].nested);
    expect(cloned.level1.array[1]).not.toBe(original.level1.array[1]);
    expect(cloned.level1.array[1][2]).not.toBe(original.level1.array[1][2]);
  });
});

