const { validateEachPlugin } = require('../../../../src/plugins/shape/duplicate');

describe('validateEachPlugin', () => {
  class ParentError extends Error {
    constructor(message) {
      super(message);
      this.name = 'ParentError';
    }
  }

  const createPlugin = (name, instanceMethods = [], staticMethods = []) => ({
    name,
    fullName: `Plugin${name}`,
    instanceMethods,
    staticMethods
  });

  test.skip('should not throw when plugins have different names and no duplicate methods', () => {
    const pluginA = createPlugin('A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('B', ['method2'], ['staticMethod2']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError)).not.toThrow();
  });

  test('should throw TypeError when plugins have the same name', () => {
    const pluginA = createPlugin('A');
    const pluginB = createPlugin('A');

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow(TypeError);
  });

  test.skip('should throw TypeError with descriptive message when plugins have the same name', () => {
    const pluginA = createPlugin('A');
    const pluginB = createPlugin('A');

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow('Plugin "A" is already defined');
  });

  test('should throw TypeError when plugins have duplicate instance methods', () => {
    const pluginA = createPlugin('A', ['method1', 'method2']);
    const pluginB = createPlugin('B', ['method2', 'method3']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow(TypeError);
  });

  test.skip('should throw TypeError with descriptive message when plugins have duplicate instance methods', () => {
    const pluginA = createPlugin('A', ['method1', 'commonMethod']);
    const pluginB = createPlugin('B', ['method2', 'commonMethod']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow('Duplicate instance method "commonMethod" found in plugins "A" and "B"');
  });

  test('should throw TypeError when plugins have duplicate static methods', () => {
    const pluginA = createPlugin('A', [], ['staticMethod1', 'staticMethod2']);
    const pluginB = createPlugin('B', [], ['staticMethod2', 'staticMethod3']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow(TypeError);
  });

  test.skip('should throw TypeError with descriptive message when plugins have duplicate static methods', () => {
    const pluginA = createPlugin('A', [], ['staticMethod1', 'commonStatic']);
    const pluginB = createPlugin('B', [], ['staticMethod2', 'commonStatic']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow('Duplicate static method "commonStatic" found in plugins "A" and "B"');
  });

  test.skip('should not throw when same plugin is compared with itself (same indices)', () => {
    const pluginA = createPlugin('A', ['method1'], ['staticMethod1']);

    expect(() => validateEachPlugin(pluginA, pluginA, 0, 0, ParentError)).not.toThrow();
  });

  test.skip('should handle empty method arrays correctly', () => {
    const pluginA = createPlugin('A', [], []);
    const pluginB = createPlugin('B', [], []);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError)).not.toThrow();
  });

  test.skip('should handle plugins with only instance methods', () => {
    const pluginA = createPlugin('A', ['method1'], []);
    const pluginB = createPlugin('B', ['method2'], []);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError)).not.toThrow();
  });

  test.skip('should handle plugins with only static methods', () => {
    const pluginA = createPlugin('A', [], ['static1']);
    const pluginB = createPlugin('B', [], ['static2']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError)).not.toThrow();
  });

  test('should throw when multiple method conflicts exist', () => {
    const pluginA = createPlugin('A', ['method1', 'common'], ['static1', 'commonStatic']);
    const pluginB = createPlugin('B', ['method2', 'common'], ['static2', 'commonStatic']);

    expect(() => validateEachPlugin(pluginA, pluginB, 0, 1, ParentError))
      .toThrow(TypeError);
  });
});

