const shouldPrefixCause = require('../../../src/merge/prefix').shouldPrefixCause;

describe('shouldPrefixCause', () => {
  test.skip('returns false when error is null', () => {
    expect(shouldPrefixCause(null, Error)).toBe(false);
  });

  test.skip('returns false when error is undefined', () => {
    expect(shouldPrefixCause(undefined, Error)).toBe(false);
  });

  test.skip('returns false when error is not an object', () => {
    expect(shouldPrefixCause('not an object', Error)).toBe(false);
    expect(shouldPrefixCause(42, Error)).toBe(false);
    expect(shouldPrefixCause(true, Error)).toBe(false);
  });

  test.skip('returns false when error has no cause property', () => {
    const error = new Error('test error');
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test.skip('returns false when cause is null', () => {
    const error = { cause: null };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test.skip('returns false when cause is undefined', () => {
    const error = { cause: undefined };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause has no name property', () => {
    const error = { cause: {} };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause.name is empty string', () => {
    const error = { cause: { name: '' } };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test.skip('returns false when cause.name is only whitespace', () => {
    const error = { cause: { name: '   ' } };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test.skip('returns false when ErrorClass is not a function', () => {
    const error = { cause: { name: 'TestError' } };
    expect(shouldPrefixCause(error, 'not a function')).toBe(false);
    expect(shouldPrefixCause(error, null)).toBe(false);
    expect(shouldPrefixCause(error, undefined)).toBe(false);
    expect(shouldPrefixCause(error, {})).toBe(false);
  });

  test('returns true when cause name matches ErrorClass name and is useful', () => {
    const error = { cause: { name: 'ReferenceError' } };
    expect(shouldPrefixCause(error, ReferenceError)).toBe(true);
  });

  test.skip('returns true when cause name is different from its constructor name', () => {
    const CustomError = function CustomError() {};
    CustomError.prototype.constructor = CustomError;

    const error = { cause: { name: 'DifferentName', constructor: { name: 'CustomError' } } };
    expect(shouldPrefixCause(error, CustomError)).toBe(true);
  });

  test('returns false when cause name equals constructor name and doesnt match ErrorClass', () => {
    const CustomError = function CustomError() {};
    CustomError.prototype.constructor = CustomError;

    const error = { cause: { name: 'CustomError', constructor: { name: 'CustomError' } } };
    expect(shouldPrefixCause(error, ReferenceError)).toBe(false);
  });

  test('handles built-in Error classes correctly', () => {
    const error = { cause: { name: 'TypeError' } };
    expect(shouldPrefixCause(error, TypeError)).toBe(true);
  });

  test('handles custom error classes with same name correctly', () => {
    const MyError = function MyError() {};
    MyError.prototype.constructor = MyError;

    const error = { cause: { name: 'MyError', constructor: { name: 'MyError' } } };
    expect(shouldPrefixCause(error, MyError)).toBe(false);
  });

  test.skip('handles error with cause that has constructor but no constructor.name', () => {
    const error = { cause: { name: 'SomeError', constructor: {} } };
    expect(shouldPrefixCause(error, Error)).toBe(true);
  });

  test('handles error with cause that has no constructor', () => {
    const error = { cause: { name: 'SomeError' } };
    expect(shouldPrefixCause(error, Error)).toBe(true);
  });
});

