// test/plugins/shape/main/normalizePluginsOpt.test.js

const { normalizePluginsOpt } = require('../../../../src/plugins/shape/main');

describe('normalizePluginsOpt', () => {
  class ParentError extends Error {
    constructor(message) {
      super(message);
      this.name = 'ParentError';
    }
  }

  class AnotherError extends Error {
    constructor(message) {
      super(message);
      this.name = 'AnotherError';
    }
  }

  it.skip('should return an empty array when plugins is not provided', () => {
    const result = normalizePluginsOpt(ParentError);
    expect(result).toEqual([]);
  });

  it.skip('should return the same array when plugins is a valid array', () => {
    const plugins = ['plugin1', 'plugin2'];
    const result = normalizePluginsOpt(ParentError, plugins);
    expect(result).toBe(plugins);
    expect(result).toEqual(['plugin1', 'plugin2']);
  });

  it.skip('should return an empty array when plugins is explicitly an empty array', () => {
    const result = normalizePluginsOpt(ParentError, []);
    expect(result).toEqual([]);
  });

  it.skip('should throw TypeError with correct message when plugins is a string', () => {
    expect(() => {
      normalizePluginsOpt(ParentError, 'invalid');
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(ParentError, 'invalid');
    } catch (error) {
      expect(error.message).toContain('ParentError');
      expect(error.message).toContain('string');
    }
  });

  it.skip('should throw TypeError with correct message when plugins is a number', () => {
    expect(() => {
      normalizePluginsOpt(ParentError, 123);
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(ParentError, 123);
    } catch (error) {
      expect(error.message).toContain('ParentError');
      expect(error.message).toContain('number');
    }
  });

  it.skip('should throw TypeError with correct message when plugins is an object', () => {
    expect(() => {
      normalizePluginsOpt(ParentError, { key: 'value' });
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(ParentError, { key: 'value' });
    } catch (error) {
      expect(error.message).toContain('ParentError');
      expect(error.message).toContain('object');
    }
  });

  it.skip('should throw TypeError with correct message when plugins is null', () => {
    expect(() => {
      normalizePluginsOpt(ParentError, null);
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(ParentError, null);
    } catch (error) {
      expect(error.message).toContain('ParentError');
      expect(error.message).toContain('null');
    }
  });

  it.skip('should throw TypeError with correct message when plugins is undefined', () => {
    expect(() => {
      normalizePluginsOpt(ParentError, undefined);
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(ParentError, undefined);
    } catch (error) {
      expect(error.message).toContain('ParentError');
      expect(error.message).toContain('undefined');
    }
  });

  it.skip('should work with different Error classes', () => {
    const plugins = ['plugin1'];
    const result = normalizePluginsOpt(AnotherError, plugins);
    expect(result).toBe(plugins);
  });

  it.skip('should throw TypeError with correct message when using different Error class', () => {
    expect(() => {
      normalizePluginsOpt(AnotherError, 'invalid');
    }).toThrow(TypeError);

    try {
      normalizePluginsOpt(AnotherError, 'invalid');
    } catch (error) {
      expect(error.message).toContain('AnotherError');
      expect(error.message).toContain('string');
    }
  });
});

