import { normalizeAllMethods } from '../../../../src/plugins/shape/methods';

describe('normalizeAllMethods', () => {
  // Mock the constants that are used in the function
  const ORIGINAL_INSTANCE_METHODS = global.INSTANCE_METHODS;
  const ORIGINAL_STATIC_METHODS = global.STATIC_METHODS;

  beforeEach(() => {
    // Set up default mock values for the constants
    global.INSTANCE_METHODS = ['method1', 'method2'];
    global.STATIC_METHODS = ['staticMethod1', 'staticMethod2'];
  });

  afterEach(() => {
    // Restore original values
    global.INSTANCE_METHODS = ORIGINAL_INSTANCE_METHODS;
    global.STATIC_METHODS = ORIGINAL_STATIC_METHODS;
    jest.clearAllMocks();
  });

  it('should normalize instance methods first, then static methods', () => {
    const plugin = {
      method1: jest.fn(),
      method2: jest.fn(),
      staticMethod1: jest.fn(),
      staticMethod2: jest.fn()
    };

    const result = normalizeAllMethods(plugin);

    expect(result).toBeDefined();
    expect(typeof result).toBe('object');
  });

  it('should handle empty plugin object', () => {
    const plugin = {};

    const result = normalizeAllMethods(plugin);

    expect(result).toEqual(expect.objectContaining({}));
  });

  it('should handle plugin with no matching methods', () => {
    const plugin = {
      unknownMethod: jest.fn(),
      anotherUnknown: jest.fn()
    };

    const result = normalizeAllMethods(plugin);

    expect(result).toBeDefined();
  });

  it('should maintain original plugin object unchanged', () => {
    const plugin = {
      method1: () => 'original',
      staticMethod1: () => 'static'
    };

    const originalPlugin = { ...plugin };
    normalizeAllMethods(plugin);

    expect(plugin).toEqual(originalPlugin);
  });

  it('should throw TypeError when plugin is null', () => {
    expect(() => normalizeAllMethods(null)).toThrow(TypeError);
  });

  it('should throw TypeError when plugin is undefined', () => {
    expect(() => normalizeAllMethods(undefined)).toThrow(TypeError);
  });

  it.skip('should throw TypeError when plugin is not an object', () => {
    expect(() => normalizeAllMethods('string')).toThrow();
    expect(() => normalizeAllMethods(123)).toThrow();
    expect(() => normalizeAllMethods(true)).toThrow();
  });

  it('should handle plugin with mixed method types', () => {
    const plugin = {
      method1: function() { return 'instance'; },
      method2: () => 'arrow',
      staticMethod1: function() { return 'static'; },
      staticMethod2: 'not a function'
    };

    const result = normalizeAllMethods(plugin);

    expect(result).toBeDefined();
    expect(typeof result).toBe('object');
  });

  it('should return object with normalized structure', () => {
    const plugin = {
      method1: jest.fn().mockReturnValue('result1'),
      method2: jest.fn().mockReturnValue('result2'),
      staticMethod1: jest.fn().mockReturnValue('static1'),
      staticMethod2: jest.fn().mockReturnValue('static2')
    };

    const result = normalizeAllMethods(plugin);

    expect(result).toBeDefined();
    expect(typeof result).toBe('object');
  });

  it('should work with custom INSTANCE_METHODS and STATIC_METHODS', () => {
    global.INSTANCE_METHODS = ['customInstance'];
    global.STATIC_METHODS = ['customStatic'];

    const plugin = {
      customInstance: jest.fn(),
      customStatic: jest.fn()
    };

    const result = normalizeAllMethods(plugin);

    expect(result).toBeDefined();
  });
});

