    expect(lastArgIsOptions(config, { valid: 'object' })).toBe(true);
    expect(lastArgIsOptions(config, 'string')).toBe(false);
    expect(lastArgIsOptions(config, 42)).toBe(false);
    expect(lastArgIsOptions(config, null)).toBe(false);
    expect(lastArgIsOptions(config, undefined)).toBe(false);
    expect(lastArgIsOptions(config, [])).toBe(true);
  });

  test.skip('should pass lastArg to isOptions function', () => {
    const config = {
      isOptions: jest.fn().mockImplementation((arg) => typeof arg === 'object'),
      fullName: 'special-plugin'
    };
    const lastArg = { option: 'value' };

    const result = lastArgIsOptions(config, lastArg);

    expect(result).toBe(true);
    expect(config.isOptions).toHaveBeenCalledWith(lastArg);
  });
});

