test/subclass/validate/validateSubclass..source:
const { validateSubclass } = require('../../../src/subclass/validate');

describe('validateSubclass', () => {
  let classesData;

  beforeEach(() => {
    // Mock the classesData set
    global.classesData = new Set();
    classesData = global.classesData;
  });

  afterEach(() => {
    // Clean up the global mock
    delete global.classesData;
  });

  // Create a proper mock subclass that mimics the structure expected by validateSubclass
  const createMockSubclass = (name) => {
    const Subclass = function() {};
    Subclass.prototype = Object.create(Error.prototype);
    Subclass.prototype.constructor = Subclass;
    Subclass.prototype.name = name;
    Subclass.subclass = createMockSubclass;
    return Subclass;
  };

  it.skip('should complete successfully when ErrorClass is in classesData', () => {
    const TestError = createMockSubclass('TestError');
    classesData.add(TestError);

    expect(() => validateSubclass(TestError)).not.toThrow();
  });

  it.skip('should throw an error when ErrorClass is not in classesData', () => {
    const TestError = createMockSubclass('TestError');

    expect(() => validateSubclass(TestError)).toThrow(
      'This class should be instantiated using `errorFactory.create`'
    );
  });

  it.skip('should handle multiple valid classes correctly', () => {
    const TestError1 = createMockSubclass('TestError1');
    const TestError2 = createMockSubclass('TestError2');
    const TestError3 = createMockSubclass('TestError3');

    classesData.add(TestError1);
    classesData.add(TestError2);

    expect(() => validateSubclass(TestError1)).not.toThrow();
    expect(() => validateSubclass(TestError2)).not.toThrow();
    expect(() => validateSubclass(TestError3)).toThrow();
  });

  it.skip('should not modify the classesData set', () => {
    const TestError = createMockSubclass('TestError');
    classesData.add(TestError);

    const snapshot = new Set(classesData);
    validateSubclass(TestError);

    expect(classesData.size).toBe(snapshot.size);
    expect([...classesData]).toEqual([...snapshot]);
  });

  it.skip('should not modify the ErrorClass or its prototype', () => {
    const TestError = createMockSubclass('TestError');
    const originalPrototype = { ...TestError.prototype };
    const originalClass = TestError.toString();

    classesData.add(TestError);
    validateSubclass(TestError);

    expect(TestError.toString()).toBe(originalClass);
    expect({ ...TestError.prototype }).toEqual(originalPrototype);
  });
});
